class Solution:
    def is_balanced(self, text: str) -> bool:
        stack = []
        mapping = {")": "(", "]": "[", "}": "{"}
        openers = set("([{")
        closers = set(")]}")

        for char in text:
            if char in openers:
                stack.append(char)
            elif char in closers:
                # 1. Check for improper closing (stack empty)
                if not stack:
                    return False

                # 2. Check for mismatch
                last_open = stack.pop()
                expected_open = mapping[char]

                if last_open != expected_open:
                    return False
            # If the character is not a bracket, it is ignored

        # After checking all characters, the stack must be empty for the brackets to be balanced
        return not stack
